import React from 'react';
import { act, create, type ReactTestRenderer } from 'react-test-renderer';
import { afterEach, expect, it, vi } from 'vitest';
import { PreviewCanvasControls } from '../../../vendor/axhub-commentary/src/ui/runtime/preview-canvas-controls';
const model = vi.hoisted(() => ({ scale: 0.7, mode: 'fit', panX: 0, panY: 0, reservedRightWidth: 360 }));
vi.mock('../../../vendor/axhub-commentary/src/utils/page-zoom-toggle', () => ({
  PAGE_LAYOUT_CHANGE_EVENT: 'commentary:page-layout-change',
  getPageZoomView: () => ({ ...model }), setPageZoomEnabled: vi.fn(), panPageZoom: vi.fn(),
  setPageZoomView: vi.fn((scale: number | string) => { model.scale = scale === 'fit' ? 0.7 : Number(scale); model.mode = scale === 'fit' ? 'fit' : 'manual'; }),
}));
import { setPageZoomView, setPageZoomEnabled } from '../../../vendor/axhub-commentary/src/utils/page-zoom-toggle';
afterEach(() => { vi.unstubAllGlobals(); vi.clearAllMocks(); vi.useRealTimers(); });
async function setup(getScopeKey?: () => string) {
  Object.assign(model, { scale: 0.7, mode: 'fit', panX: 0, panY: 0, reservedRightWidth: 360 });
  const owner = new EventTarget(); let frameId = 0; const frames = new Map<number, FrameRequestCallback>();
  vi.stubGlobal('window', Object.assign(owner, { requestAnimationFrame: (callback: FrameRequestCallback) => { frames.set(++frameId, callback); return frameId; }, cancelAnimationFrame: (id: number) => frames.delete(id) }));
  vi.stubGlobal('document', { activeElement: null, documentElement: { style: { getPropertyValue: () => '', getPropertyPriority: () => '', setProperty: vi.fn(), removeProperty: vi.fn() } } });
  const releaseRef = { current: () => {} }; let view!: ReactTestRenderer;
  await act(async () => { view = create(React.createElement(PreviewCanvasControls, { active: true, docked: true, hasTarget: false, releaseRef, getScopeKey, onInteractionChange: vi.fn() })); });
  await act(async () => { for (let i = 0; i < 2; i++) { const pending = [...frames.values()]; frames.clear(); pending.forEach(callback => callback(0)); } });
  return { view, owner, releaseRef };
}
it('shows the effective percentage and offers zoom, fit and reset actions', async () => {
  const { view } = await setup();
  const button = (name: string) => view.root.findByProps({ 'aria-label': name });
  expect(button('画布缩放比例').props.value).toBe('70');
  await act(async () => button('放大画布').props.onClick());
  expect(setPageZoomView).toHaveBeenLastCalledWith(0.8);
  await act(async () => button('适应画布宽度').props.onClick());
  expect(setPageZoomView).toHaveBeenLastCalledWith('fit');
  await act(async () => button('重置画布视图').props.onClick());
  expect(setPageZoomView).toHaveBeenLastCalledWith(1);
  await act(async () => button('画布缩放比例').props.onChange({ target: { value: '150' } }));
  expect(setPageZoomView).toHaveBeenLastCalledWith(1.5);
  await act(async () => view.unmount());
});
it('releases layout synchronously before native panels open and detaches shortcuts on unmount', async () => {
  const { view, owner, releaseRef } = await setup();
  releaseRef.current();
  expect(setPageZoomEnabled).toHaveBeenLastCalledWith(false, { owner: 'canvas-controls' });
  await act(async () => view.unmount());
  vi.mocked(setPageZoomView).mockClear();
  const event = new Event('keydown', { cancelable: true }); Object.assign(event, { key: '+', ctrlKey: true });
  owner.dispatchEvent(event);
  expect(setPageZoomView).not.toHaveBeenCalled();
});
it('handles canvas shortcuts and leaves editing fields and their browser zoom shortcuts alone', async () => {
  const { view, owner } = await setup();
  const press = (key: string, editing = false) => {
    const event = new Event('keydown', { cancelable: true });
    Object.assign(event, { key, ctrlKey: true, composedPath: () => editing ? [{ matches: () => true }] : [] });
    owner.dispatchEvent(event); return event;
  };
  await act(async () => { expect(press('+').defaultPrevented).toBe(true); });
  expect(setPageZoomView).toHaveBeenLastCalledWith(0.8);
  vi.mocked(setPageZoomView).mockClear();
  await act(async () => { expect(press('+', true).defaultPrevented).toBe(false); });
  expect(setPageZoomView).not.toHaveBeenCalled();
  await act(async () => { press('0'); });
  expect(setPageZoomView).toHaveBeenLastCalledWith(1);
  await act(async () => view.unmount());
});
it('resets the view when the displayed page scope changes', async () => {
  vi.useFakeTimers(); let scope = 'a';
  const { view } = await setup(() => scope);
  await act(async () => view.root.findByProps({ 'aria-label': '放大画布' }).props.onClick());
  vi.mocked(setPageZoomView).mockClear(); scope = 'b';
  await act(async () => { vi.advanceTimersByTime(500); });
  expect(setPageZoomView).toHaveBeenLastCalledWith('fit');
  await act(async () => view.unmount());
});
it('consumes the click generated by a pan gesture without blocking the next normal click', async () => {
  const { view, owner } = await setup();
  await act(async () => view.root.findByProps({ 'aria-label': '拖动画布' }).props.onClick());
  const action = vi.fn(); owner.addEventListener('click', action);
  const pointer = (type: string, x: number, y: number) => {
    const event = new Event(type, { cancelable: true }); Object.assign(event, { pointerId: 1, button: 0, clientX: x, clientY: y }); owner.dispatchEvent(event);
  };
  await act(async () => { pointer('pointerdown', 100, 100); pointer('pointermove', 120, 120); pointer('pointerup', 120, 120); });
  const click = new Event('click', { cancelable: true }); Object.assign(click, { detail: 1, clientX: 120, clientY: 120 }); owner.dispatchEvent(click);
  expect(click.defaultPrevented).toBe(true); expect(action).not.toHaveBeenCalled();
  owner.dispatchEvent(new Event('click')); expect(action).toHaveBeenCalledOnce();
  await act(async () => view.unmount());
});
